UPDATE public.drills AS drill
SET
  focus = catalog.focus,
  duration = catalog.duration,
  rating = catalog.rating,
  verified = catalog.verified,
  description = catalog.description,
  cues = catalog.cues,
  tags = catalog.tags,
  media_url = catalog.media_url,
  min_players = catalog.min_players,
  max_players = catalog.max_players,
  optimal_group_size = catalog.optimal_group_size,
  level = catalog.level,
  intensity = catalog.intensity,
  positions_emphasis = catalog.positions_emphasis,
  requires_full_court = catalog.requires_full_court,
  is_template = catalog.is_template
FROM catalog
WHERE drill.coach_id IS NULL
  AND drill.name = catalog.name;

