INSERT INTO public.drills (
  coach_id,
  name,
  focus,
  duration,
  rating,
  verified,
  description,
  cues,
  tags,
  media_url,
  min_players,
  max_players,
  optimal_group_size,
  level,
  intensity,
  positions_emphasis,
  requires_full_court,
  is_template
)
SELECT
  catalog.coach_id,
  catalog.name,
  catalog.focus,
  catalog.duration,
  catalog.rating,
  catalog.verified,
  catalog.description,
  catalog.cues,
  catalog.tags,
  catalog.media_url,
  catalog.min_players,
  catalog.max_players,
  catalog.optimal_group_size,
  catalog.level,
  catalog.intensity,
  catalog.positions_emphasis,
  catalog.requires_full_court,
  catalog.is_template
FROM catalog
WHERE NOT EXISTS (
  SELECT 1
  FROM public.drills AS existing
  WHERE existing.coach_id IS NULL
    AND existing.name = catalog.name
);

DO $$
BEGIN
  IF (
    SELECT COUNT(DISTINCT name)
    FROM public.drills
    WHERE coach_id IS NULL
      AND name = ANY (ARRAY['Form Shooting', 'Mikan Series', 'Reverse Mikan', 'Free Throw Routine', 'Spot-Up Shooting — 5 Spots', 'Pull-Up Series — 1-Dribble', 'Step-Back Series', 'Two-Ball Pound', 'Two-Ball Alternating', 'Cone Weave Handle', 'In-Out to Cross Combo', 'Behind-the-Back Series', 'Hesitation Series', 'Weak-Hand Only', 'Euro-Step Finishes', 'Floater Series', 'Spin Move Finish', '3-Man Weave', '4-Corners Passing', 'Partner Chest Pass', 'Partner Bounce Pass', 'Skip Pass Reads', 'Paint Touch Kicks', 'Shell Defense 4v4', 'Help & Recover', 'Closeout & Contest', 'Zig-Zag Defense', 'Box-Out Gauntlet', 'Outlet & Fill', 'Baseline Sprints', 'Suicides (Line Runs)', 'Lane Agility Test', 'Baseline-to-Baseline Repeats', 'Ball Screen Pull-Up', 'Pistol Action (DHO)', 'Hammer Action', 'Star Shooting (5-Spot)', 'Chair Shooting — Curls & Fades', 'Drive-Kick-Swing 3s', 'PnR Reads — Drop Coverage', 'PnR Reads — Switch & Slip', 'Post Entry & 45 Cut', 'Relocation Shooting', 'Nail Help Scramble (2v2+Coach)', 'Baseline Drift Coverage', 'Corner Closeouts', 'Shell + Ball Screen Layer', '3-Man Weave into 3v2', '4-Man Weave into 2v1', 'Skip to Extra', 'Numbers Advantage — 5v4', 'Full-Court Conditioning — 17s', '30-30-30 Runs', 'Shuttle Sprints (Pro)', 'Zoom Action Reads', 'Ghost Screen 3s', 'Drift-Corner Series', 'Punch Post Seal', 'Laker Cut Finishes', 'Iverson Cut Catch & Shoot', 'Floppy Action Var 1', 'Floppy Action Var 2', 'Staggered Screens Reads', 'Spain PnR Finisher', 'Chicago Action (Pin+DHO)', 'Zoom Flip Late Clock', 'Short Roll Playmaking', 'Skip to Hammer', 'Nash Dribble Under', 'Lift & Drift Shooting', 'Stack Inbounds Quick 3', 'Baseline Rip Screen', 'Wedge Screen Post-Up', 'Spain Twist Variation', 'Double Drag Options', 'Drag into Throwback 3', 'Empty-Side PnR Reads', 'Veer Back Read', 'Pitch Ahead Layups', 'Deep Seal Duck-Ins', 'Punch to Split Cut', 'Wide Pindown to DHO', 'Pindown Slip & Pop', 'Post Split to Corner 3', 'K-Slide Closeout Chain', 'Gap & Go Contest', 'Tag-The-Roller Scramble', 'Early Shrink Then Fly', 'Weakside X-Out Drill', 'Top-Lock Denial', 'Ice to Peel Switch', 'Hot-Nail Stunt Timing', 'Post Front & Scram', 'Two to the Ball Blitz', 'Late Switch Communication', 'Low-Man Take & Go', 'No Middle Contain', 'High-Wall on PnR', 'Switch-Back Drill', 'Charger Circle (Safety)', 'Veer Box-Out', 'Hit-First Rebound', 'Triangle Rebound War', 'Second Effort Closeout', 'Drive & Drift Kicks', 'One-More Chains', 'High-Low Hi-Lo Reps', 'Lob Timing Window', 'Baseline Skip Series', 'Inside-Out Post Kicks', 'Paint Touch to Pitch', 'Swing-Swing Corner 3', 'Advance Pass Races', 'Backdoor Read vs Deny', 'Touch Pass Shooting', 'Two-Player Keep-Away', 'Give-and-Go Ladder', 'Elbow Entry Options', 'Middle Third Advance', 'Full-Court 10-5-10s', 'Gassers on the :30', 'Half-Court L Builds', '3-6-9 Sprint Pyramid', 'Four-Corner Sprint Cycle', 'Ladder Sprints', '3-2-1 Tempo Runs', 'Continuous Transition Maker', 'Cone T-Agility', 'Pro Agility 5-10-5', 'Mirror Footwork', 'Push-Pull Sprint Sets', 'Split Reads', 'Inside-Out Series', 'Tag Coverage', 'Pitch Patterns', 'Cut Reads', 'Skip Series', 'Ladder Sets', 'Touch Pass Chain', 'Gasser Sets', 'Contain Rotation', 'Shuttle Test', 'Skip Chain', 'One-More Series', 'Pitch Chain', 'Ladder Test', 'Agility Tempo', 'Interval Sets', 'Gap Chain', 'Inside-Out Chain', 'Switch Coverage', 'High-Low Patterns', 'Fade Flow', 'Paint Touch Timing', 'Pyramid Cycle', 'Hammer Flow', 'Scram Rotation', 'Drive-Kick Quick', 'Inside-Out Timing', 'Ice Rotation', 'Split Options', 'Short Roll Finishes', 'Backdoor Chain', 'Agility Cycle', 'Lob Series', 'Ice Coverage', 'Pitch Timing', 'Fade Options', 'Hammer Quick', 'Relocate Flow', 'Repeat Challenge', 'Ladder Challenge', 'Swing Window', 'Nail Drill', 'Tag Drill', 'Pyramid Sets', 'Gasser Challenge', 'Lift Reads', 'Agility Challenge', 'Low-Man Coverage', 'High-Low Timing', 'Backdoor Timing', 'Swing Chain', 'Punch Reads', 'Tag Discipline', 'Relocate Reads', 'Agility Sets', 'Low-Man Drill', 'Contain Drill', 'Punch Flow', 'Lift Flow', 'Blitz Rotation', 'Peel Coverage', 'Ladder Tempo', 'Swing Timing', 'Switch Discipline', 'Gap Drill', 'Repeat Test', 'Tag Chain', 'Chicago Action Var']::TEXT[])
  ) <> 200 THEN
    RAISE EXCEPTION 'Expected all 200 canonical CoachVision drills after seeding.';
  END IF;
END $$;
